// MTap background music - original songs synthesized live with WebAudio.
// No audio files, no samples, no licensing questions: every note comes from
// oscillators and noise playing patterns generated by this code.
//
// v4 engine: real song structure (intro -> verse -> build -> DROP -> verse ->
// build -> DROP -> breakdown, 24 bars before repeating), six genres (house /
// trance / drum & bass / synthwave / rock / metal), a tempo-synced echo send,
// and a daily remix - the puzzle number seeds the key, tempo feel, chord
// progression, and rhythm patterns, so every day sounds different.

import { mulberry32 } from './rng.js';

let ctx = null;
let master = null;
let padGain = null;
let schedulerTimer = null;
let nextNoteTime = 0;
let step = 0; // global 16th-note counter
let playing = false;
let padOscs = [];
let currentPadKey = -1;
let song = null; // the composed arrangement for this session
let echo = null;          // tempo-synced feedback delay (the lead/arp send)
let echoFeedback = null;
let echoOut = null;        // echo return level (muted for the pre-drop gap)

const STEPS_PER_BAR = 16;

const f = (semis) => 440 * Math.pow(2, semis / 12);

// ---- iOS unlock ----
// On iPhone, WebAudio is muted by the physical ring/silent switch (Safari runs it
// in the "ambient" audio session). Playing a looping, silent <audio> element -
// which must start inside a user gesture - flips the session to "playback", after
// which WebAudio (music + sound effects) is audible regardless of the switch.
let unlockEl = null;

function silentWavUrl() {
  const rate = 8000;
  const n = rate;
  const buf = new ArrayBuffer(44 + n * 2);
  const v = new DataView(buf);
  const writeStr = (off, s) => { for (let i = 0; i < s.length; i++) v.setUint8(off + i, s.charCodeAt(i)); };
  writeStr(0, 'RIFF'); v.setUint32(4, 36 + n * 2, true); writeStr(8, 'WAVE');
  writeStr(12, 'fmt '); v.setUint32(16, 16, true); v.setUint16(20, 1, true); v.setUint16(22, 1, true);
  v.setUint32(24, rate, true); v.setUint32(28, rate * 2, true); v.setUint16(32, 2, true); v.setUint16(34, 16, true);
  writeStr(36, 'data'); v.setUint32(40, n * 2, true);
  return URL.createObjectURL(new Blob([buf], { type: 'audio/wav' }));
}

export function unlockIosAudio() {
  try {
    if (!unlockEl) {
      unlockEl = new Audio(silentWavUrl());
      unlockEl.loop = true;
      unlockEl.volume = 0.01;
      unlockEl.setAttribute('playsinline', '');
    }
    const p = unlockEl.play();
    if (p && p.catch) p.catch(() => { /* retried on next gesture */ });
    if (ctx && ctx.state === 'suspended') ctx.resume();
    if (playing && trackMode && trackEl && trackEl.paused) playTrackEl();
  } catch { /* audio unavailable */ }
}

// ---- audio graph ----

function ensureCtx() {
  if (!ctx) {
    ctx = new (window.AudioContext || window.webkitAudioContext)();
    master = ctx.createGain();
    master.gain.value = 0;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.ratio.value = 6;
    master.connect(comp).connect(ctx.destination);
    padGain = ctx.createGain();
    padGain.gain.value = 0.0;
    padGain.connect(master);
    // Echo send: a tempo-synced feedback delay (3/8 beat, set per song) that
    // leads and arps feed for instant EDM polish. Darkened in the loop so
    // repeats melt into the pad instead of cluttering the top end.
    echo = ctx.createDelay(1.5);
    echoFeedback = ctx.createGain();
    echoFeedback.gain.value = 0.34;
    const echoTone = ctx.createBiquadFilter();
    echoTone.type = 'lowpass';
    echoTone.frequency.value = 2400;
    echo.connect(echoTone).connect(echoFeedback).connect(echo);
    echoOut = ctx.createGain();
    echoOut.gain.value = 0.5;
    echo.connect(echoOut).connect(master);
  }
  if (ctx.state === 'suspended') ctx.resume();
}

function env(t, attack, peak, decay, dest) {
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(peak, t + attack);
  g.gain.exponentialRampToValueAtTime(0.0001, t + attack + decay);
  g.connect(dest || master);
  return g;
}

const driveCurves = new Map();
function driveCurve(amount) {
  if (!driveCurves.has(amount)) {
    const n = 1024;
    const curve = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      const x = (i / (n - 1)) * 2 - 1;
      curve[i] = Math.tanh(x * amount);
    }
    driveCurves.set(amount, curve);
  }
  return driveCurves.get(amount);
}

// ---- instruments ----

function kick(t, punch = 0.5) {
  const o = ctx.createOscillator();
  o.type = 'sine';
  o.frequency.setValueAtTime(130, t);
  o.frequency.exponentialRampToValueAtTime(42, t + 0.09);
  o.connect(env(t, 0.002, punch, 0.22));
  o.start(t); o.stop(t + 0.3);
  padGain.gain.cancelScheduledValues(t);
  padGain.gain.setValueAtTime(0.05, t);
  padGain.gain.linearRampToValueAtTime(0.28, t + song.stepDur * 3.4);
}

function noiseBurst(t, len, filterType, freq, peak) {
  const buf = ctx.createBuffer(1, Math.max(1, ctx.sampleRate * len), ctx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / data.length);
  const src = ctx.createBufferSource();
  src.buffer = buf;
  const filt = ctx.createBiquadFilter();
  filt.type = filterType;
  filt.frequency.value = freq;
  src.connect(filt).connect(env(t, 0.001, peak, len));
  src.start(t);
}

const clap = (t, g = 0.22) => noiseBurst(t, 0.16, 'bandpass', 1700, g);
const snare = (t, g = 0.2) => { noiseBurst(t, 0.14, 'highpass', 2200, g); kickless(t, 190, 0.12, g * 0.6); };
const hatClosed = (t, g = 0.07) => noiseBurst(t, 0.04, 'highpass', 8500, g);
const hatOpen = (t, g = 0.06) => noiseBurst(t, 0.12, 'highpass', 7500, g);
const crash = (t, g = 0.11) => noiseBurst(t, 0.55, 'highpass', 5200, g);
const impact = (t) => { // the DROP hit: sub boom + crash together
  const o = ctx.createOscillator();
  o.type = 'sine';
  o.frequency.setValueAtTime(72, t);
  o.frequency.exponentialRampToValueAtTime(34, t + 0.4);
  o.connect(env(t, 0.004, 0.55, 0.5));
  o.start(t); o.stop(t + 0.55);
  crash(t, 0.16);
};

function kickless(t, freq, dur, peak) { // tonal thump used inside snare
  const o = ctx.createOscillator();
  o.type = 'triangle';
  o.frequency.value = freq;
  o.connect(env(t, 0.002, peak, dur));
  o.start(t); o.stop(t + dur + 0.05);
}

function bassNote(t, semis, dur, peak, cutoff) {
  const o = ctx.createOscillator();
  o.type = 'sawtooth';
  o.frequency.value = f(semis);
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.setValueAtTime(cutoff, t);
  lp.frequency.exponentialRampToValueAtTime(Math.max(120, cutoff * 0.25), t + dur);
  lp.Q.value = 5;
  o.connect(lp).connect(env(t, 0.004, peak, dur));
  o.start(t); o.stop(t + dur + 0.05);
}

function subNote(t, semis, dur, peak) {
  const o = ctx.createOscillator();
  o.type = 'sine';
  o.frequency.value = f(semis - 12);
  o.connect(env(t, 0.005, peak, dur));
  o.start(t); o.stop(t + dur + 0.05);
}

// Distorted guitar: root + fifth (+octave) saws through a tanh waveshaper.
function guitar(t, semis, dur, drive, peak, cutoff) {
  const shaper = ctx.createWaveShaper();
  shaper.curve = driveCurve(drive);
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.value = cutoff;
  const g = env(t, 0.004, peak, dur);
  shaper.connect(lp).connect(g);
  for (const iv of [0, 7, 12]) {
    const o = ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.value = f(semis + iv);
    o.detune.value = iv === 0 ? -4 : 4;
    o.connect(shaper);
    o.start(t); o.stop(t + dur + 0.05);
  }
}

function stab(t, tones, peak) {
  for (const semis of tones) {
    const o = ctx.createOscillator();
    o.type = 'sine';
    o.frequency.value = f(semis);
    o.connect(env(t, 0.004, peak, 0.4));
    o.start(t); o.stop(t + 0.45);
  }
}

function lead(t, semis, peak, bright) {
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.setValueAtTime(bright ? 3400 : 2600, t);
  lp.frequency.exponentialRampToValueAtTime(700, t + 0.14);
  lp.Q.value = 4;
  const g = env(t, 0.004, peak, 0.16);
  lp.connect(g);
  const send = ctx.createGain();
  send.gain.value = 0.35;
  lp.connect(send).connect(echo);
  for (const detune of [-6, 6]) {
    const o = ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.value = f(semis);
    o.detune.value = detune;
    o.connect(lp);
    o.start(t); o.stop(t + 0.2);
  }
}

// Bright 16th-note pluck that feeds the echo — the trance/synthwave sparkle.
function arpNote(t, semis, peak = 0.05) {
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.setValueAtTime(5200, t);
  lp.frequency.exponentialRampToValueAtTime(900, t + 0.1);
  const g = env(t, 0.002, peak, 0.12);
  lp.connect(g);
  const send = ctx.createGain();
  send.gain.value = 0.45;
  lp.connect(send).connect(echo);
  const o = ctx.createOscillator();
  o.type = 'square';
  o.frequency.value = f(semis);
  o.connect(lp);
  o.start(t); o.stop(t + 0.15);
}

// Six detuned saws — the classic trance supersaw, for leads and drop chords.
function supersaw(t, semis, dur, peak, withEcho = true) {
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.setValueAtTime(3800, t);
  lp.frequency.exponentialRampToValueAtTime(1200, t + dur);
  lp.Q.value = 1.5;
  const g = env(t, 0.01, peak, dur);
  lp.connect(g);
  if (withEcho) {
    const send = ctx.createGain();
    send.gain.value = 0.3;
    lp.connect(send).connect(echo);
  }
  for (const detune of [-14, -8, -3, 3, 8, 14]) {
    const o = ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.value = f(semis);
    o.detune.value = detune;
    o.connect(lp);
    o.start(t); o.stop(t + dur + 0.05);
  }
}

// Deep rolling DnB sub: a sine an octave below the bass with a soft attack.
function dnbSub(t, semis, dur, peak = 0.32) {
  const o = ctx.createOscillator();
  o.type = 'sine';
  o.frequency.value = f(semis - 24);
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(peak, t + 0.03);
  g.gain.setValueAtTime(peak, t + dur * 0.7);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  g.connect(master);
  o.connect(g);
  o.start(t); o.stop(t + dur + 0.05);
}

// Big 80s gated snare: bandpass noise cut off hard — synthwave's signature.
function gatedSnare(t, g = 0.3) {
  noiseBurst(t, 0.26, 'bandpass', 1400, g);
  noiseBurst(t, 0.26, 'highpass', 3600, g * 0.5);
  kickless(t, 165, 0.18, g * 0.55);
}

function tom(t, freq, g = 0.22) {
  const o = ctx.createOscillator();
  o.type = 'sine';
  o.frequency.setValueAtTime(freq, t);
  o.frequency.exponentialRampToValueAtTime(freq * 0.55, t + 0.2);
  o.connect(env(t, 0.003, g, 0.26));
  o.start(t); o.stop(t + 0.3);
}

function riser(t, dur) {
  const buf = ctx.createBuffer(1, ctx.sampleRate * dur, ctx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * (i / data.length);
  const src = ctx.createBufferSource();
  src.buffer = buf;
  const bp = ctx.createBiquadFilter();
  bp.type = 'bandpass';
  bp.Q.value = 1.5;
  bp.frequency.setValueAtTime(300, t);
  bp.frequency.exponentialRampToValueAtTime(6000, t + dur);
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(0.13, t + dur);
  g.gain.linearRampToValueAtTime(0.0001, t + dur + 0.05);
  src.connect(bp).connect(g).connect(master);
  src.start(t);
}

function padChord(key, tones, t) {
  if (key === currentPadKey) return;
  currentPadKey = key;
  for (const o of padOscs) { try { o.stop(t + 0.05); } catch { /* ok */ } }
  padOscs = [];
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.value = 1100;
  lp.connect(padGain);
  for (const semis of tones) {
    for (const detune of [-7, 7]) {
      const o = ctx.createOscillator();
      o.type = 'sawtooth';
      o.frequency.value = f(semis);
      o.detune.value = detune;
      o.connect(lp);
      o.start(t);
      padOscs.push(o);
    }
  }
}

