function genMask(rng, density) {
  const m = [];
  for (let i = 0; i < 16; i++) m.push(rng() < density ? 1 : 0);
  m[0] = 1; // always land on the downbeat
  return m;
}

function genLeadPattern(rng, density) {
  const p = [];
  for (let i = 0; i < 16; i++) p.push(rng() < density ? Math.floor(rng() * 3) : -1);
  return p;
}

// ---- Hatikvah ----
// Israel's national anthem: Samuel Cohen's 1888 setting of a 16th-century
// melody (public domain). Transcribed from the D-minor LilyPond score on
// Wikipedia's "Hatikvah" article. Each note is [midi, sixteenths]; the second
// half of the refrain repeats, as sung.
const HK_VERSE_A = [
  [62, 2], [64, 2], [65, 2], [67, 2], [69, 4], [69, 4],
  [70, 2], [69, 2], [70, 2], [74, 2], [69, 8],
  [67, 4], [67, 2], [67, 2], [65, 4], [65, 4],
];
const HK_CADENCE_1 = [[64, 2], [62, 2], [64, 2], [65, 2], [62, 6], [57, 2]];
const HK_CADENCE_2 = [[64, 2], [62, 2], [64, 2], [65, 2], [62, 8]];
const HK_REFRAIN_A = [
  [62, 4], [74, 4], [74, 4], [74, 4], [72, 2], [74, 2], [72, 2], [70, 2], [69, 8],
  [62, 4], [74, 4], [74, 4], [74, 4], [72, 2], [74, 2], [72, 2], [70, 2], [69, 8],
];
const HK_REFRAIN_B = [
  [72, 4], [72, 2], [72, 2], [65, 4], [65, 4],
  [67, 2], [69, 2], [70, 2], [72, 2], [69, 4], [67, 2], [65, 2],
  [67, 4], [67, 4], [65, 4], [65, 2], [65, 2],
  [64, 2], [62, 2], [64, 2], [65, 2], [62, 8],
];
const HK_MELODY = [
  ...HK_VERSE_A, ...HK_CADENCE_1, ...HK_VERSE_A, ...HK_CADENCE_2,
  ...HK_REFRAIN_A, ...HK_REFRAIN_B, ...HK_REFRAIN_B,
];
// One chord per half bar (20 bars). Voicings sit below the melody.
const HK_CHORD_TONES = {
  Dm: [50, 53, 57], Gm: [55, 58, 62], A: [49, 52, 57], C: [48, 52, 55], F: [53, 57, 60], Bb: [50, 53, 58],
};
const HK_BASS = { Dm: 38, Gm: 43, A: 45, C: 36, F: 41, Bb: 46 };
const HK_VERSE_CHORDS = ['Dm', 'Dm', 'Gm', 'Dm', 'Gm', 'Dm', 'A', 'Dm'];
const HK_REFRAIN_B_CHORDS = ['F', 'F', 'Gm', 'F', 'Gm', 'Dm', 'A', 'Dm'];
const HK_CHORDS = [
  ...HK_VERSE_CHORDS, ...HK_VERSE_CHORDS,
  'Dm', 'Dm', 'C', 'F', 'Bb', 'Bb', 'C', 'F',
  ...HK_REFRAIN_B_CHORDS, ...HK_REFRAIN_B_CHORDS,
];
const HK_BARS = 20;
export const HATIKVAH_SCORE = { melody: HK_MELODY, chords: HK_CHORDS, bars: HK_BARS };

// v4.5 "Hatikvah — big-room remix" (family request: more upbeat, straight into
// the song, a real drop, more instruments). 128 BPM, no intro, no breakdown —
// the melody starts on beat one and every bar is the anthem:
//   bars 0-5   verse on piano + vocal chops, snaps & shaker; kick/bass/pad join
//   bars 6-7   build: snare roll, riser, pad opens, kick drops out, a beat of silence
//   bars 8-15  DROP 1: supersaw + vocal-chop lead, offbeat brass stabs,
//              pumping pad, rolling bass, full drums
//   bar  15    mini build (half-bar roll + gap)
//   bars 16-19 DROP 2: the repeated last line, biggest — adds bells and a high arp
// then straight back to bar 0.
// v4.6: the anthem now loops as CHAPTERS that keep building — see hkBpm below.
const HK_BPM = 128;
function composeHatikvah() {
  const melody = new Map();
  let at = 0;
  for (const [midi, len] of HK_MELODY) { melody.set(at, { semis: midi - 69, len }); at += len; }
  return {
    style: 'hatikvah',
    bpm: HK_BPM,
    stepDur: 60 / HK_BPM / 4,
    melody,
    totalSteps: HK_BARS * STEPS_PER_BAR,
  };
}

// Pop piano: triangle fundamental + sine overtones, fast decay.
function piano(t, semis, dur, peak) {
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.setValueAtTime(3600, t);
  lp.frequency.exponentialRampToValueAtTime(1100, t + 0.5);
  const g = ctx.createGain();
  const ring = Math.max(0.3, Math.min(dur, 1.4));
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(peak, t + 0.004);
  g.gain.exponentialRampToValueAtTime(peak * 0.35, t + 0.22);
  g.gain.exponentialRampToValueAtTime(0.0001, t + ring + 0.25);
  lp.connect(g).connect(master);
  const send = ctx.createGain();
  send.gain.value = 0.12;
  g.connect(send).connect(echo);
  for (const [type, mult, amp, detune] of [['triangle', 1, 1, 0], ['sine', 1, 0.5, 6], ['sine', 2, 0.35, 0], ['sine', 3, 0.12, 0]]) {
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.value = f(semis) * mult;
    o.detune.value = detune;
    const a = ctx.createGain();
    a.gain.value = amp;
    o.connect(a).connect(lp);
    o.start(t); o.stop(t + ring + 0.3);
  }
}

// Pop-EDM vocal chop: saws through "ah" formant filters with a little pitch
// scoop into each note.
function vocalChop(t, semis, dur, peak) {
  const len = Math.min(dur * 0.92, 0.55);
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(peak, t + 0.012);
  g.gain.setValueAtTime(peak, t + Math.max(0.02, len - 0.05));
  g.gain.exponentialRampToValueAtTime(0.0001, t + len + 0.04);
  g.connect(master);
  const send = ctx.createGain();
  send.gain.value = 0.28;
  g.connect(send).connect(echo);
  const formants = [[760, 7, 1], [1180, 9, 0.6], [2700, 12, 0.25]].map(([freq, q, amp]) => {
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.value = freq;
    bp.Q.value = q;
    const a = ctx.createGain();
    a.gain.value = amp * 3.2;
    bp.connect(a).connect(g);
    return bp;
  });
  for (const detune of [-7, 7]) {
    const o = ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.setValueAtTime(f(semis - 0.8), t);
    o.frequency.exponentialRampToValueAtTime(f(semis), t + 0.045);
    o.detune.value = detune;
    for (const bp of formants) o.connect(bp);
    o.start(t); o.stop(t + len + 0.08);
  }
}

// Short brassy chord stab: saws with a snapping filter envelope.
function brassStab(t, tones, peak) {
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.Q.value = 2;
  lp.frequency.setValueAtTime(700, t);
  lp.frequency.linearRampToValueAtTime(3400, t + 0.025);
  lp.frequency.exponentialRampToValueAtTime(900, t + 0.2);
  const g = env(t, 0.006, peak, 0.2);
  lp.connect(g);
  for (const semis of tones) {
    for (const detune of [-10, 10]) {
      const o = ctx.createOscillator();
      o.type = 'sawtooth';
      o.frequency.value = f(semis);
      o.detune.value = detune;
      o.connect(lp);
      o.start(t); o.stop(t + 0.25);
    }
  }
}

const shaker = (t, g = 0.035) => noiseBurst(t, 0.05, 'highpass', 6500, g);
const snap = (t, g = 0.14) => { noiseBurst(t, 0.07, 'bandpass', 2800, g); noiseBurst(t, 0.02, 'highpass', 7500, g * 0.6); };

// Glockenspiel sparkle doubling the tune on the last drop.
function bell(t, semis, peak) {
  const o = ctx.createOscillator();
  o.type = 'sine';
  o.frequency.value = f(semis + 12);
  const g = env(t, 0.003, peak, 0.9);
  const send = ctx.createGain();
  send.gain.value = 0.3;
  g.connect(send).connect(echo);
  o.connect(g);
  o.start(t); o.stop(t + 1);
}

// Pad level for bars with no kick to pump it.
function padLevel(t, level, ramp) {
  padGain.gain.cancelScheduledValues(t);
  padGain.gain.setValueAtTime(padGain.gain.value, t);
  padGain.gain.linearRampToValueAtTime(level, t + ramp);
}

const hkSemis = (chord) => HK_CHORD_TONES[chord].map((m) => m - 69);
const HK_ARP = [0, 1, 2, 1];
const HK_PIANO_HITS = new Set([0, 3, 6, 8, 11, 14]); // syncopated pop-piano comp

// v4.6 "keeps building": every pass through the anthem is a new CHAPTER that
// hits harder and runs faster than the last. Chapter c (0, 1, 2, ...):
//   level      min(c, 3)  — what joins the mix (see scheduleHatikvah)
//   tempo      128 → 131 → 134 → 137 → 140 BPM, ramped across the last
//              4 bars of each chapter so it speeds up under you, then holds
//   key        up a half step at chapter 2 and again at chapter 4
const hkBpm = (c) => HK_BPM + 3 * Math.min(c, 4);
const hkTranspose = (c) => (c >= 4 ? 2 : c >= 2 ? 1 : 0);
const ride = (t, g = 0.035) => { noiseBurst(t, 0.28, 'bandpass', 9500, g); noiseBurst(t, 0.06, 'highpass', 6000, g * 0.6); };

function scheduleHatikvah(globalStep, t) {
  const SPB = STEPS_PER_BAR;
  const chapter = Math.floor(globalStep / song.totalSteps);
  const L = Math.min(chapter, 3);
  const s = globalStep % song.totalSteps;
  const bar = Math.floor(s / SPB);
  const x = s % SPB;
  const half = Math.floor(s / 8);
  const tr = hkTranspose(chapter);
  const chord = HK_CHORDS[half];
  const tones = hkSemis(chord).map((m) => m + tr);
  const root = HK_BASS[chord] - 69 + 12 + tr;

  // Tempo: hold the chapter's BPM, then ramp toward the next one over bars 16-19.
  const from = hkBpm(chapter), to = hkBpm(chapter + 1);
  const ramp = bar >= 16 ? (s - 16 * SPB) / (4 * SPB) : 0;
  song.stepDur = 60 / (from + (to - from) * ramp) / 4;
  song.bpm = from;

  const drop = bar >= 8;
  const drop2 = bar >= 16;
  const build = bar === 6 || bar === 7;             // the big build into drop 1
  const miniBuild = bar === 15 && x >= 8;           // the lift into drop 2
  const gap = (bar === 7 && x >= 12) || (bar === 15 && x >= 14);
  const kickFrom = chapter === 0 ? 2 : 0;           // after the first time it's straight in

  // ---- punctuation ----
  if (x === 0) {
    if (bar === 8 || bar === 16) impact(t);
    if (bar === 0 && chapter > 0) {
      if (L >= 2) impact(t); else crash(t, 0.1);
      echo.delayTime.setTargetAtTime(song.stepDur * 6, t, 0.3); // keep the echo on the beat
    }
    if (bar === 6) riser(t, song.stepDur * (SPB * 2 - 4));
    if (bar === 15) riser(t, song.stepDur * (SPB - 2));
    if (bar === 0) padLevel(t, 0.1 + 0.03 * L, 0.3);
    if (bar === 6) padLevel(t, 0.2, song.stepDur * SPB * 2); // opens up through the build
    // Big chapters: a crash every 4 bars of the drops.
    if (L >= 3 && drop && bar % 4 === 0 && bar !== 8 && bar !== 16) crash(t, 0.07);
  }
  if (bar === 15 && x === 8) crash(t, 0.06);

  // ---- melody (every bar) ----
  const note = song.melody.get(s);
  if (note) {
    // Notes in a build bar stop at the gap so the silence is real.
    const gapAt = bar === 7 ? 12 : bar === 15 ? 14 : SPB;
    const dur = Math.min(note.len, gapAt - x) * song.stepDur;
    const n = note.semis + tr;
    if (!drop) {
      if (L >= 2 && !build) {
        // Later verses ride on a filtered pluck-saw + chops instead of solo piano.
        supersaw(t, n + 12, dur, 0.026 + 0.006 * (L - 2));
        piano(t, n + 12, dur, 0.07);
        vocalChop(t, n, dur, 0.05);
      } else {
        piano(t, n + 12, dur, 0.13);
        if (bar >= 4 || L >= 1) vocalChop(t, n, dur, L >= 1 ? 0.06 : 0.05); // the hook
      }
    } else {
      supersaw(t, n + 12, dur, drop2 ? 0.075 : 0.065);
      vocalChop(t, n, dur, drop2 ? 0.09 : 0.08);
      if (drop2 || L >= 2) bell(t, n + 12, 0.03);
      if (L >= 2) supersaw(t, n, dur, 0.035, false);       // octave-down double: wider
      if (L >= 3 && drop2) supersaw(t, n + 24, dur, 0.025, false); // and the sky-high one
    }
  }
  if (gap) { // THE GAP: a beat of nothing, then the drop
    if ((bar === 7 && x === 12) || (bar === 15 && x === 14)) { padLevel(t, 0.0001, 0.03); echoOut.gain.setTargetAtTime(0, t, 0.015); echoOut.gain.setTargetAtTime(0.5, t + (SPB - x) * song.stepDur, 0.005); }
    return;
  }

  // ---- harmony ----
  padChord(half, tones, t);
  if (!drop && !(L >= 2 && !build) && HK_PIANO_HITS.has(x)) {
    const v = x === 0 || x === 8 ? 0.06 : 0.04;
    for (const semis of tones) piano(t, semis, song.stepDur * 3, v);
    if (x === 0 || x === 8) piano(t, root - 12, song.stepDur * 8, 0.07);
  }
  // Later verses: offbeat brass + a rolling 8th arp keep the energy up.
  if (!drop && !build && L >= 2 && x % 8 === 6) brassStab(t, tones.map((m) => m + 12), 0.026);
  if (!drop && !build && L >= 1 && x % 2 === 0) arpNote(t, tones[HK_ARP[(x >> 1) % 4]] + 24, 0.014);
  if (drop && x % 4 === 2) brassStab(t, tones.map((m) => m + 12), (drop2 ? 0.05 : 0.042) + 0.004 * L);
  if (drop && x % 2 === 0 && (drop2 || L >= 1 || x % 4 === 0)) {
    arpNote(t, tones[HK_ARP[(x >> 1) % 4]] + 24 + (x % 8 >= 4 ? 12 : 0), 0.02);
  }

  // ---- drums ----
  const kicking = drop ? !miniBuild : bar >= kickFrom && bar < 7;
  const kickVol = drop ? 0.58 : L >= 2 ? 0.54 : 0.48;
  if (kicking && x % 4 === 0) kick(t, kickVol);
  if (drop && !miniBuild && (x === 4 || x === 12)) { clap(t, 0.2); if (L >= 1) snare(t, 0.08); }
  if (!drop && !build && (x === 4 || x === 12)) { if (L >= 2) clap(t, 0.13); else snap(t, 0.13); }
  if (!build && !miniBuild) shaker(t, x % 4 === 2 ? 0.045 : 0.025);
  if ((drop || L >= 2) && !build && x % 4 === 2) hatOpen(t, 0.05);
  if ((drop || L >= 1) && !build && x % 2 === 1) hatClosed(t, 0.03);
  if (drop && L >= 1 && !miniBuild && x % 2 === 0 && x % 4 !== 0) hatClosed(t, 0.02); // 16th hats
  if (drop && L >= 2 && x % 4 === 0) ride(t, 0.03);
  // Fill into every 4th bar of the big drops.
  if (drop && L >= 3 && !miniBuild && bar % 4 === 3 && x >= 12) tom(t, 110 + (x - 12) * 30, 0.12);

  // Build: snare roll 4ths -> 8ths -> 16ths, rising. From chapter 1 claps double
  // it; from chapter 2 the KICK rolls too (quarters -> 8ths), Tiësto style.
  if (build) {
    const k = (bar - 6) * SPB + x; // 0..27
    const every = k < 8 ? 4 : k < 16 ? 2 : 1;
    if (k % every === 0) { snare(t, 0.06 + k * 0.005); if (L >= 1) clap(t, 0.05 + k * 0.004); }
    if (bar === 7 && x >= 8 && x % 2 === 0) tom(t, 90 + (x - 8) * 22, 0.12);
    if (bar === 7 && L >= 2 && x % 2 === 0) kick(t, 0.4 + x * 0.008);
  }
  if (miniBuild && x < 14) {
    snare(t, 0.1 + (x - 8) * 0.02);
    if (L >= 2 && x <= 12 && x % 2 === 0) kick(t, 0.38 + (x - 8) * 0.02); // stops short of the gap
  }

  // ---- bass ----
  if (drop && !miniBuild) {
    if (x % 4 === 0) subNote(t, root, 0.2, 0.28);
    // Chapter 2+: bouncy octave bass on the offbeat — more bump.
    else bassNote(t, root + (L >= 2 && x % 4 === 2 ? 12 : 0), 0.11, 0.2, 1500 + 300 * L);
  } else if (!drop && bar >= kickFrom && !build) {
    if (L >= 2 && x % 4 === 2) bassNote(t, root + 12, 0.1, 0.15, 1000);
    else if (L >= 2 && x % 4 === 3) bassNote(t, root, 0.08, 0.11, 900);
    else if (L < 2 && x % 4 === 2) bassNote(t, root, 0.16, 0.2, 800);
  } else if (!drop && bar < kickFrom && (x === 0 || x === 8)) {
    subNote(t, root, song.stepDur * 7, 0.18);
  }
}

export function composeSong(styleName, daySeed) {
  if (styleName === 'hatikvah') return composeHatikvah();
  const def = STYLE_DEFS[styleName] || STYLE_DEFS.house;
  const rng = mulberry32((daySeed * 2654435761 + styleName.length * 97) >>> 0);
  const keyShift = Math.floor(rng() * 5) - 2;                    // -2..+2 semitones
  const bpm = def.bpm + Math.floor(rng() * 9) - 4;               // +/-4 BPM
  const prog = def.progressions[Math.floor(rng() * def.progressions.length)];
  const bars = prog.map((c) => {
    const root = c.r + keyShift;
    const tones = QUALITIES[c.q].map((iv) => root + iv);
    return { root, tones };
  });
  const totalBars = ARRANGEMENT.reduce((a, s) => a + s.bars, 0);
  const sectionAt = [];
  let barCursor = 0;
  for (const s of ARRANGEMENT) {
    for (let b = 0; b < s.bars; b++) sectionAt.push({ name: s.name, barInSection: b, sectionBars: s.bars });
    barCursor += s.bars;
  }
  return {
    style: styleName,
    bpm,
    stepDur: 60 / bpm / 4,
    bars,
    sectionAt,
    totalSteps: totalBars * STEPS_PER_BAR,
    verseLead: genLeadPattern(rng, 0.35),
    dropLead: genLeadPattern(rng, 0.6),
    chugMask: genMask(rng, styleName === 'metal' ? 0.75 : 0.5),
    verseChug: genMask(rng, 0.4),
  };
}

// ---- the scheduler ----

function scheduleStep(globalStep, t) {
  if (song.style === 'hatikvah') { scheduleHatikvah(globalStep, t); return; }
  const s = globalStep % song.totalSteps;
  const bar = Math.floor(s / STEPS_PER_BAR);
  const sixteenth = s % STEPS_PER_BAR;
  const sec = song.sectionAt[bar];
  const chord = song.bars[bar % song.bars.length];
  const isLastBuildBar = sec.name === 'build' && sec.barInSection === sec.sectionBars - 1;

  // THE GAP: the last two 16ths before a drop go silent - then the drop slams in.
  if (isLastBuildBar && sixteenth >= 14) return;

  // Section-start punctuation
  if (sixteenth === 0 && sec.barInSection === 0) {
    if (sec.name === 'drop') impact(t);
    else if (sec.name !== 'intro') crash(t, 0.09);
    if (sec.name === 'build') riser(t, song.stepDur * (STEPS_PER_BAR * sec.sectionBars - 2));
  }

  const st = song.style;
  const inGroove = sec.name === 'verse' || sec.name === 'drop' || sec.name === 'build';
  const isDrop = sec.name === 'drop';

  // Pad: the electronic styles keep it running (ducked by the kick = sidechain
  // pump); intro/break for all styles.
  const padded = st === 'house' || st === 'trance' || st === 'dnb' || st === 'synthwave';
  if (padded || sec.name === 'intro' || sec.name === 'break') {
    padChord(bar % song.bars.length, chord.tones, t);
  }

  // Build-section roll: density doubles over the last bar.
  if (sec.name === 'build') {
    const rollEvery = isLastBuildBar ? (sixteenth >= 8 ? 1 : 2) : 4;
    if (sixteenth % rollEvery === 0) (padded ? clap : snare)(t, 0.1 + (sixteenth / 16) * 0.12);
  }

  if (st === 'house') {
    if (inGroove && sixteenth % 4 === 0) kick(t, isDrop ? 0.55 : 0.45);
    if (inGroove && sec.name !== 'build' && (sixteenth === 4 || sixteenth === 12)) clap(t);
    if (inGroove && sixteenth % 4 === 2) bassNote(t, chord.root - 12, 0.18, 0.26, 900);
    if (isDrop && sixteenth % 4 === 0) subNote(t, chord.root - 12, 0.22, 0.3);
    if ((sec.name === 'verse' || isDrop) && (sixteenth === 2 || sixteenth === 6)) stab(t, chord.tones, 0.045);
    if (inGroove && sixteenth % 2 === 1) hatClosed(t, isDrop ? 0.08 : 0.06);
    if (isDrop && sixteenth % 8 === 6) hatOpen(t);
    const pat = isDrop ? song.dropLead : song.verseLead;
    if ((sec.name === 'verse' || isDrop) && pat[sixteenth] >= 0) {
      lead(t, chord.tones[pat[sixteenth]] + (isDrop ? 24 : 12), isDrop ? 0.075 : 0.055, isDrop);
    }
  } else if (st === 'trance') {
    if (inGroove && sixteenth % 4 === 0) kick(t, isDrop ? 0.55 : 0.45);
    if (inGroove && sec.name !== 'build' && (sixteenth === 4 || sixteenth === 12)) clap(t, 0.15);
    // The trance signature: a rolling offbeat bassline filling every 16th
    // between kicks, opening up on the drop.
    if (inGroove && sixteenth % 4 !== 0) bassNote(t, chord.root - 12, 0.11, isDrop ? 0.24 : 0.17, isDrop ? 1500 : 800);
    if (isDrop && sixteenth % 4 === 0) subNote(t, chord.root - 12, 0.2, 0.26);
    if (sec.name === 'verse' || isDrop) {
      const steps = [0, 1, 2, 1];
      arpNote(t, chord.tones[steps[sixteenth % 4]] + 12 + (sixteenth % 8 >= 4 ? 12 : 0), isDrop ? 0.05 : 0.035);
    }
    if (inGroove && sixteenth % 2 === 1) hatClosed(t, 0.06);
    if (isDrop && sixteenth % 8 === 6) hatOpen(t);
    const pat = isDrop ? song.dropLead : song.verseLead;
    if (isDrop && pat[sixteenth] >= 0) supersaw(t, chord.tones[pat[sixteenth]] + 24, 0.22, 0.06);
  } else if (st === 'dnb') {
    // Two-step break: kick 0 & 10, snare on the 2 and 4, shuffled 16th hats.
    if (inGroove && (sixteenth === 0 || sixteenth === 10)) kick(t, 0.5);
    if (inGroove && sec.name !== 'build' && (sixteenth === 4 || sixteenth === 12)) snare(t, 0.22);
    if (inGroove && sixteenth === 15) snare(t, 0.07); // ghost into the next bar
    if (inGroove) hatClosed(t, sixteenth % 2 ? 0.05 : 0.028);
    if (inGroove && (sixteenth === 0 || sixteenth === 7)) dnbSub(t, chord.root, song.stepDur * 6, isDrop ? 0.34 : 0.26);
    if (isDrop && (sixteenth === 2 || sixteenth === 9)) stab(t, chord.tones, 0.04);
    const pat = isDrop ? song.dropLead : song.verseLead;
    if ((sec.name === 'verse' || isDrop) && pat[sixteenth] >= 0 && sixteenth % 2 === 0) {
      lead(t, chord.tones[pat[sixteenth]] + 12, 0.05, isDrop);
    }
  } else if (st === 'synthwave') {
    // Half-time 100 BPM cruise: kick 1 & the and-of-3, huge gated snare on 3.
    if (inGroove && (sixteenth === 0 || sixteenth === 10)) kick(t, 0.48);
    if (inGroove && sec.name !== 'build' && sixteenth === 8) gatedSnare(t, isDrop ? 0.32 : 0.26);
    if (inGroove && sixteenth % 2 === 0) hatClosed(t, 0.04);
    if (inGroove && sixteenth % 2 === 0) bassNote(t, chord.root - 12, 0.2, 0.2, 700); // pulsing 8ths
    if (sec.name === 'verse' || isDrop) {
      const steps = [0, 2, 1, 2];
      if (sixteenth % 2 === 0) arpNote(t, chord.tones[steps[(sixteenth >> 1) % 4]] + 12, 0.04);
    }
    const pat = isDrop ? song.dropLead : song.verseLead;
    if (isDrop && pat[sixteenth] >= 0 && sixteenth % 2 === 0) supersaw(t, chord.tones[pat[sixteenth]] + 24, 0.32, 0.05);
    // Rolling tom fill out of the build — pure 1985.
    if (isLastBuildBar && sixteenth >= 8 && sixteenth < 14 && sixteenth % 2 === 0) tom(t, 220 - (sixteenth - 8) * 18);
  } else if (st === 'rock') {
    if (inGroove && (sixteenth === 0 || sixteenth === 6 || sixteenth === 8 || sixteenth === 14)) kick(t, 0.5);
    if (inGroove && sec.name !== 'build' && (sixteenth === 4 || sixteenth === 12)) snare(t);
    if (inGroove && sixteenth % 2 === 0) bassNote(t, chord.root - 12, 0.14, 0.22, 600);
    if (sec.name === 'verse' && sixteenth === 0) guitar(t, chord.root, 1.4, 3.5, 0.16, 2800);
    if (isDrop && song.chugMask[sixteenth]) guitar(t, chord.root, 0.11, 5, 0.14, 1100);
    if (isDrop && sixteenth === 0) guitar(t, chord.root, 0.9, 4, 0.15, 3000);
    if (inGroove && sixteenth % 2 === 1) hatClosed(t, 0.05);
    const pat = isDrop ? song.dropLead : song.verseLead;
    if (isDrop && pat[sixteenth] >= 0) lead(t, chord.tones[pat[sixteenth]] + 24, 0.06, true);
  } else { // metal
    const mask = isDrop ? song.chugMask : song.verseChug;
    if (inGroove && mask[sixteenth]) {
      guitar(t, chord.root, 0.09, 7, 0.15, 950);       // palm-mute chug
      kick(t, 0.42);                                    // double-kick shadows the riff
      bassNote(t, chord.root, 0.09, 0.18, 500);
    }
    if (inGroove && sec.name !== 'build' && (sixteenth === 4 || sixteenth === 12)) snare(t, 0.24);
    if (isDrop && sixteenth === 0) guitar(t, chord.root, 1.2, 6, 0.16, 3200); // open ring
    if (inGroove && sixteenth % 4 === 2) hatClosed(t, 0.05);
  }

  // Breakdown: sparse echo of the lead over the pad.
  if (sec.name === 'break' && (sixteenth === 0 || sixteenth === 6 || sixteenth === 10)) {
    lead(t, chord.tones[sixteenth % 3] + 12, 0.05, false);
  }
}

function schedulerTick() {
  while (nextNoteTime < ctx.currentTime + 0.25) {
    scheduleStep(step, nextNoteTime);
    step++;
    nextNoteTime += song.stepDur;
  }
}

// ---- the produced Hatikvah record (v4.7) ----
// Hatikvah is now a real production, rendered offline by the studio in studio/
// (see studio/STUDIO.md) and streamed from an AAC file through a media element:
// it starts while still downloading and never holds the whole song as PCM (a
// phone-friendly ~0 MB instead of ~80 MB). The song has a real ending; when it
// finishes it starts again from the top. If the file can't load or decode, the
// live-synth arrangement above takes over.
const TRACK_URL = 'audio/hatikvah.m4a';   // relative to the page (Vite base './')
const TRACK_LEVEL = 0.85;                 // mastered at ~-10 LUFS; bypasses the synth compressor
let trackEl = null;
let trackGain = null;
let trackMode = false;
let trackFailed = false;
let trackSeed = 1;

function ensureTrack() {
  if (trackEl) return true;
  try {
    trackEl = new Audio();
    trackEl.preload = 'auto';
    trackEl.setAttribute('playsinline', '');
    trackEl.src = TRACK_URL;
    trackGain = ctx.createGain();
    trackGain.gain.value = 0;
    // Through WebAudio so ducking/fades work on iOS (element.volume is read-only there).
    ctx.createMediaElementSource(trackEl).connect(trackGain).connect(ctx.destination);
    trackEl.addEventListener('ended', () => {
      if (!playing || !trackMode) return;
      setTimeout(() => { if (playing && trackMode) { trackEl.currentTime = 0; playTrackEl(); } }, 900);
    });
    trackEl.addEventListener('error', () => {
      trackFailed = true;
      if (playing && trackMode) { stopMusic(true); startMusic('hatikvah', trackSeed); }
    });
    return true;
  } catch {
    trackFailed = true;
    trackEl = null;
    return false;
  }
}

function playTrackEl() {
  const p = trackEl.play();
  if (p && p.catch) p.catch(() => { /* autoplay blocked: retried on the next tap (unlockIosAudio) */ });
}

function startTrack(daySeed) {
  if (!ensureTrack()) return false;
  trackSeed = daySeed;
  trackMode = true;
  playing = true;
  const t = ctx.currentTime;
  trackGain.gain.cancelScheduledValues(t);
  trackGain.gain.setValueAtTime(0.0001, t);
  trackGain.gain.linearRampToValueAtTime(TRACK_LEVEL, t + 0.6);
  try { trackEl.currentTime = 0; } catch { /* not seekable yet: starts at 0 anyway */ }
  playTrackEl();
  return true;
}

// ---- public API ----

export const MUSIC_STYLES = ['house', 'trance', 'dnb', 'synthwave', 'rock', 'metal'];

export function startMusic(styleName = 'house', daySeed = 1) {
  unlockIosAudio();
  ensureCtx();
  if (playing) return;
  if (styleName === 'hatikvah' && !trackFailed && startTrack(daySeed)) return;
  playing = true;
  song = composeSong(styleName, daySeed);
  echo.delayTime.setValueAtTime(song.stepDur * 6, ctx.currentTime); // dotted 8th
  step = 0;
  currentPadKey = -1;
  nextNoteTime = ctx.currentTime + 0.1;
  master.gain.cancelScheduledValues(ctx.currentTime);
  master.gain.setValueAtTime(0.0001, ctx.currentTime);
  master.gain.linearRampToValueAtTime(0.42, ctx.currentTime + 1.2);
  schedulerTimer = setInterval(schedulerTick, 100);
}

export function stopMusic(immediate = false) {
  if (!playing) return;
  playing = false;
  if (trackMode) {
    trackMode = false;
    const t = ctx.currentTime;
    trackGain.gain.cancelScheduledValues(t);
    trackGain.gain.setValueAtTime(trackGain.gain.value, t);
    trackGain.gain.linearRampToValueAtTime(0.0001, t + (immediate ? 0.02 : 0.7));
    const el = trackEl;
    setTimeout(() => { if (!trackMode) el.pause(); }, immediate ? 30 : 750);
    return;
  }
  clearInterval(schedulerTimer);
  if (ctx && master) {
    master.gain.cancelScheduledValues(ctx.currentTime);
    master.gain.setValueAtTime(master.gain.value, ctx.currentTime);
    master.gain.linearRampToValueAtTime(0.0001, ctx.currentTime + 0.7);
    const stopAt = ctx.currentTime + 0.8;
    for (const o of padOscs) { try { o.stop(stopAt); } catch { /* ok */ } }
    padOscs = [];
    currentPadKey = -1;
  }
}

export function isMusicPlaying() { return playing; }

// Debug/test readout for the streamed Hatikvah record.
export function trackDebug() {
  return { trackMode, failed: trackFailed, paused: trackEl ? trackEl.paused : null, time: trackEl ? trackEl.currentTime : null, gain: trackGain ? trackGain.gain.value : null };
}

// Briefly dip the music so a sound effect (the arrow confirm) cuts through.
export function duckMusic(ms = 400) {
  if (!ctx || !master || !playing) return;
  const t = ctx.currentTime;
  if (trackMode) {
    trackGain.gain.cancelScheduledValues(t);
    trackGain.gain.setValueAtTime(trackGain.gain.value, t);
    trackGain.gain.linearRampToValueAtTime(TRACK_LEVEL * 0.25, t + 0.03);
    trackGain.gain.linearRampToValueAtTime(TRACK_LEVEL, t + Math.max(0.2, ms / 1000));
    return;
  }
  master.gain.cancelScheduledValues(t);
  master.gain.setValueAtTime(master.gain.value, t);
  master.gain.linearRampToValueAtTime(0.1, t + 0.03);
  master.gain.linearRampToValueAtTime(0.42, t + Math.max(0.2, ms / 1000));
}
